import {onMessage, sendMessage, ProcessingRequest} from "@/public/messaging";
import {DownloadTask} from "@/public/DownloadTask";
import {startOffscreenServer} from "@monetize.software/sdk-extension/offscreen";

console.log("Offscreen document initialized");

// Paywall SDK single source of truth: BillingClient/AuthClient live here and are
// shared with the sidepanel via the port router installed in the service worker.
// Persists auth session and bootstrap cache in this document's localStorage.
startOffscreenServer({
    paywallId: "377",
    apiOrigin: "https://platform.fastica.dev",
    auth: true,
});

onMessage('startProcessing', async (message) => {
    const data = message.data as ProcessingRequest;
    console.log("Offscreen: starting processing for", data.url);

    const task = DownloadTask.disposeExistingAndCreate({
        taskId: data.taskId,
        tabId: data.tabId,
        url: data.url,
        dltype: 0,
        html: data.html,
        currentDepth: 0,
        isMultiPage: data.isMultiPage,
        maxDepth: data.maxDepth,
        params: { title: data.title },
    });

    let result: Awaited<ReturnType<typeof DownloadTask.runChain>>;
    try {
        result = await DownloadTask.runChain(task);
    } catch (e) {
        // runChain rejected on a genuine failure (network/parse error). Without
        // this catch no message would be sent and the sidepanel would hang on
        // "Downloading..." forever. Signal it like an aborted run; the sidepanel
        // surfaces the error for any task the user didn't deliberately cancel.
        console.error("Offscreen: runChain failed", e);
        sendMessage('cancel', data.taskId);
        return;
    }

    // Fire-and-forget: don't await, the background only needs the notification
    // and we avoid blocking this handler on the round-trip
    if (result) {
        sendMessage('dataPrepared', result);
    } else {
        sendMessage('cancel', data.taskId);
    }
});

onMessage('cancelProcessing', async ({ data: taskId }) => {
    DownloadTask.dispose(taskId as string);
});
